erDiagram
    USER ||--o{ ORDER : places
    ORDER ||--|{ ITEM  : contains
    USER {
        int    id
        string name
        string email
    }
    ORDER {
        int  id
        date placed_at
    }
    ITEM {
        int    id
        string sku
        int    qty
    }

classDiagram
    class Block {
        +String kind
        +render() Element
    }
    class Section {
        +String id
        +String title
        +List~Block~ blocks
    }
    class Table {
        +List headers
        +List rows
    }
    Block <|-- Section
    Block <|-- Table
